input.content:
#!/usr/bin/env node
// Throwaway mock runner for panel button-testing, port 3291 (per PanelDev
// charter: never fire action endpoints at live bots on 3201-3208). Mimics
// just enough of runner.js's public API for panel.mjs's WAKE/STOP flow.
import http from 'node:http';

let currentTask = null;
let taskCounter = 0;

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve) => {
    let data = '';
    req.on('data', (c) => (data += c));
    req.on('end', () => {
      try { resolve(JSON.parse(data || '{}')); } catch { resolve({}); }
    });
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1:3291');
  if (req.method === 'GET' && url.pathname === '/status') {
    return sendJson(res, 200, {
      name: 'MockBot',
      connected: true,
      pos: { x: 1, y: 90, z: 1 },
      health: 20,
      food: 20,
      gamemode: 'survival',
      inventory: [],
      currentTask,
      lastError: null,
      idleGuard: true,
      deathCount: 0,
      lastDeath: null,
      engine: 'mock',
    });
  }
  if (req.method === 'GET' && url.pathname === '/events') {
    return sendJson(res, 200, { events: [], last: 0 });
  }
  if (req.method === 'POST' && url.pathname === '/collect') {
    const body = await readBody(req);
    taskCounter++;
    currentTask = {
      id: `mock-${taskCounter}`,
      kind: 'collect',
      source: body.source ?? 'http',
      state: 'running',
      detail: 'mock sweep in progress',
      result: null,
      finishedAt: null,
    };
    return sendJson(res, 200, { ok: true, task: currentTask });
  }
  if (req.method === 'POST' && url.pathname === '/stop') {
    if (currentTask) { currentTask.state = 'cancelled'; currentTask.finishedAt = new Date().toISOString(); }
    return sendJson(res, 200, { ok: true, task: currentTask });
  }
  sendJson(res, 404, { error: 'not found' });
});

server.listen(3291, '127.0.0.1', () => console.log('[mock-runner] on 127.0.0.1:3291'));

